command:
const token = canvas.tokens.controlled[0] ?? game.user.character?.getActiveTokens()[0];
const actor = token?.actor ?? game.user.character;
if (!actor) return ui.notifications.warn("请先选中持妖刀的角色或令牌。");
const weapon = actor.itemTypes.weapon.find((w) => (w.system.traits?.otherTags ?? []).includes("jiuli-katana"));
const wslug = weapon?.system.slug ?? "";
const bonus = wslug.includes("greater") ? 3 : wslug.includes("moderate") ? 2 : 1;
const slug = "jiuli-enticing";
const old = actor.itemTypes.effect.filter((e) => e.slug === slug);
if (old.length) await actor.deleteEmbeddedDocuments("Item", old.map((i) => i.id));
const effect = {
  name: "诱人诅咒（妖刀·隐里切）",
  type: "effect",
  img: "icons/magic/death/mouth-bite-fangs-red.webp",
  system: {
    slug,
    description: { value: `<p>本回合内，你以妖刀·隐里切进行的攻击与伤害获得 +${bonus} 状态加值。</p>` },
    rules: [
      { key: "FlatModifier", selector: ["attack", "attack-roll"], type: "status", value: bonus, label: "诱人诅咒" },
      { key: "FlatModifier", selector: "damage", type: "status", value: bonus, label: "诱人诅咒" }
    ],
    traits: { value: ["curse", "magical"], rarity: "rare", otherTags: ["jiuli-katana"] },
    level: { value: 4 },
    duration: { value: 1, unit: "rounds", sustained: false, expiry: "turn-end" },
    tokenIcon: { show: true }
  }
};
await actor.createEmbeddedDocuments("Item", [effect]);
ui.notifications.info(`${actor.name}：诱人诅咒 +${bonus}（本回合，以妖刀攻击时生效）。`);
